// Define the possible time units.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TimeUnit {
    Year,
    Month,
    Week,
    Day,
    Hour,
    Minute,
    Second,
    Millisecond,
    Microsecond,
    Nanosecond,
    Picosecond,
    Femtosecond,
    Attosecond,
}

// A 64‐bit signed duration, pairing a magnitude with a unit.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TimeDelta64 {
    pub magnitude: i64,
    pub unit: TimeUnit,
}

/// Constructs a `TimeDelta64` from a given signed 64‐bit `value`
/// and a `unit`. Assumes `value` is already in the valid range
/// of an `i64` (i.e. between −2^63 and 2^63−1).
pub fn timedelta64(value: i64, unit: TimeUnit) -> TimeDelta64 {
    TimeDelta64 { magnitude: value, unit }
}

